import { cn } from '@tajdin/ui/lib/utils';

/** Paths from assets/brand/tajdin-mark-*.svg (generated by scripts/brand-logo.py). */
const SUN =
  'M95 400 A161 161 0 0 1 417 400 M95 400 L12 400 M116.5 319.5 L44.7 278 M175.5 260.5 L134 188.7 M256 239 L256 156 M336.5 260.5 L378 188.7 M395.5 319.5 L467.3 278 M417 400 L500 400';
const WAVE = 'M174.2 361.8 A90.3 90.3 0 0 1 337.8 361.8';

/**
 * The deq Roj mark: half-sun arc, seven rays, broadcast arc and centre dot.
 * `live` lights the wave and dot green, echoing the animated toolbar icon.
 */
export function RojMark({ className, live = false, title }: { className?: string; live?: boolean; title?: string }) {
  return (
    <svg
      viewBox="-10 130 532 304"
      className={cn('text-brand', className)}
      role={title ? 'img' : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title}
    >
      <path d={SUN} fill="none" stroke="currentColor" strokeWidth="41.5" strokeLinecap="round" strokeLinejoin="round" />
      <path
        d={WAVE}
        fill="none"
        strokeWidth="29.3"
        strokeLinecap="round"
        className={cn('transition-[stroke,opacity] duration-500', live ? 'stroke-live' : 'stroke-current opacity-50')}
      />
      <circle cx="256" cy="400" r="29.3" className={cn('transition-[fill] duration-500', live ? 'fill-live' : 'fill-current')} />
    </svg>
  );
}

export function Wordmark({ className, live }: { className?: string; live?: boolean }) {
  return (
    <span className={cn('flex items-center gap-2', className)}>
      <RojMark className="h-4 w-auto" live={live} />
      <span className="font-semibold tracking-tight">Tajdîn</span>
    </span>
  );
}
